package com.ke.ticketsystemke.service;import com.ke.ticketsystemke.entity.*;import com.ke.ticketsystemke.repository.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class WarrantyReminderGenerationServiceTest{@Mock WarrantyClaimRepository claims;@Mock WarrantyReplacementRepository replacements;@Mock WarrantyAttachmentRepository attachments;@Mock WarrantyReminderRepository reminders;@Mock WarrantyReminderGenerationRunRepository runs;@Mock EmployeeRepository employees;@Mock WarrantyDocumentRequirementService documents;WarrantyReminderGenerationService service;LocalDate today=LocalDate.now(ZoneId.of("Asia/Kolkata"));
 @BeforeEach void setup(){service=new WarrantyReminderGenerationService(claims,replacements,attachments,reminders,runs,employees,new WarrantyPendingActionCalculator(),documents);ReflectionTestUtils.setField(service,"longPendingDays",30);ReflectionTestUtils.setField(service,"level1",2);ReflectionTestUtils.setField(service,"level2",5);ReflectionTestUtils.setField(service,"level3",10);lenient().when(runs.save(any())).thenAnswer(i->i.getArgument(0));lenient().when(replacements.findByWarrantyClaim_IdInAndActiveTrue(any())).thenReturn(List.of());lenient().when(attachments.findActiveCategoriesByClaimIds(any())).thenReturn(List.of());lenient().when(employees.findByEmployeeIdLowercaseIn(any())).thenReturn(List.of());lenient().when(reminders.findByDeduplicationKey(anyString())).thenReturn(Optional.empty());lenient().when(reminders.findByStatusIn(any())).thenReturn(List.of());lenient().when(reminders.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));}
 @Test void generatesOverdueFollowUpAndVisitWithEscalation(){WarrantyClaim c=claim(1);c.setState(WarrantyClaimState.VISIT_PENDING);c.setManufacturerComplaintNumber("C1");c.setComplaintRegisteredDate(today.minusDays(20));c.setExpectedVisitDate(today.minusDays(6));c.setNextFollowUpDate(today.minusDays(6));when(claims.findAllForTracker()).thenReturn(List.of(c));service.generate();ArgumentCaptor<WarrantyReminder> cap=ArgumentCaptor.forClass(WarrantyReminder.class);verify(reminders,atLeast(2)).saveAndFlush(cap.capture());assertThat(cap.getAllValues()).extracting(WarrantyReminder::getReminderType).contains(WarrantyReminderType.FOLLOW_UP_OVERDUE,WarrantyReminderType.EXPECTED_VISIT_OVERDUE);assertThat(cap.getAllValues()).anyMatch(r->r.getEscalationLevel()==WarrantyEscalationLevel.LEVEL_2);}
 @Test void generatesMissingDocumentOwnerAndLongPending(){WarrantyClaim c=claim(2);c.setWarrantyOwnerEmployeeId(null);ReflectionTestUtils.setField(c,"markedWarrantyAt",today.minusDays(40).atStartOfDay(ZoneId.of("Asia/Kolkata")).toInstant());when(claims.findAllForTracker()).thenReturn(List.of(c));when(documents.billRuleApplies(c)).thenReturn(true);service.generate();ArgumentCaptor<WarrantyReminder> cap=ArgumentCaptor.forClass(WarrantyReminder.class);verify(reminders,atLeast(3)).saveAndFlush(cap.capture());assertThat(cap.getAllValues()).extracting(WarrantyReminder::getReminderType).contains(WarrantyReminderType.WARRANTY_OWNER_MISSING,WarrantyReminderType.REQUIRED_DOCUMENTS_MISSING,WarrantyReminderType.LONG_PENDING_WARRANTY_CASE);assertThat(cap.getAllValues()).filteredOn(r->r.getReminderType()==WarrantyReminderType.LONG_PENDING_WARRANTY_CASE).allMatch(r->r.getPriority()==WarrantyReminderPriority.CRITICAL);}
 @Test void repeatedLogicalFactUsesExistingReminder(){WarrantyClaim c=claim(3);when(claims.findAllForTracker()).thenReturn(List.of(c));WarrantyReminder existing=new WarrantyReminder();existing.setStatus(WarrantyReminderStatus.OPEN);when(reminders.findByDeduplicationKey(anyString())).thenReturn(Optional.of(existing));service.generate();verify(reminders,never()).saveAndFlush(any());verify(reminders,atLeastOnce()).save(existing);}
 @Test void staleConditionIsAutomaticallyResolved(){when(claims.findAllForTracker()).thenReturn(List.of());WarrantyReminder stale=new WarrantyReminder();stale.setStatus(WarrantyReminderStatus.OPEN);WarrantyClaim c=claim(4);stale.setWarrantyClaim(c);stale.setDeduplicationKey("old");when(reminders.findByStatusIn(any())).thenReturn(List.of(stale));service.generate();assertThat(stale.getStatus()).isEqualTo(WarrantyReminderStatus.RESOLVED);assertThat(stale.getResolvedAt()).isNotNull();}
 private WarrantyClaim claim(long id){Ticket t=new Ticket();t.setId(id);t.setTicketNumber("KE-"+id);t.setCustomerName("Customer");t.setProductType("TV");t.setStatus(TicketStatus.IN_PROGRESS);WarrantyClaim c=new WarrantyClaim();ReflectionTestUtils.setField(c,"id",id);Instant now=Instant.now();ReflectionTestUtils.setField(c,"createdAt",now);ReflectionTestUtils.setField(c,"markedWarrantyAt",now);c.setTicket(t);c.setActive(true);c.setState(WarrantyClaimState.COMPLAINT_REQUIRED);c.setResult(WarrantyClaimResult.PENDING);c.setManufacturerName("Maker");c.setModelNumber("M1");c.setWarrantyOwnerEmployeeId("EMP1");return c;}}
